import {useState, useEffect} from 'react'
import {Spinner} from '@primer/react'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {VerifiedHTMLDiv} from '@github-ui/safe-html/VerifiedHTML'
import type {SafeHTMLString} from '@github-ui/safe-html'

export interface SearchResultsProps {
  searchQuery: string
  searchType?: string
}

export function SearchResults({searchQuery, searchType}: SearchResultsProps) {
  interface SearchResult {
    redirectUrl?: string
    resultsFragment?: string
  }

  const [searchResult, setSearchResult] = useState<SearchResult | null>(null)
  const [isLoading, setIsLoading] = useState(true) // Add a loading state
  const [error, setError] = useState<string | null>(null) // Add an error state
  const [currentQuery, setCurrentQuery] = useState(searchQuery)
  const [currentSearchType, setCurrentSearchType] = useState(searchType)

  const performSearch = async (query: string, type?: string) => {
    const url =
      type === 'audit_log_queries'
        ? '/stafftools/search/search_audit_log_queries_async'
        : '/stafftools/search/search_results_async'

    setIsLoading(true)
    setError(null) // Clear any previous errors
    try {
      const params = new URLSearchParams({query})
      const result = await verifiedFetchJSON(`${url}?${params}`, {method: 'GET'})
      if (!result.ok) throw new Error(`HTTP ${result.status}${result.statusText}`)
      const json = await result.json()
      setSearchResult(json)
      const event = new CustomEvent('search.results-loaded', {detail: {searchQuery: query, searchType: type}})
      window.dispatchEvent(event)
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error'
      setError(`Search failed: (${errorMessage}).`)
      setSearchResult(null)
    } finally {
      setIsLoading(false)
    }
  }

  useEffect(() => {
    // Set up button click handlers
    const form = document.getElementById('stafftools-search-form')
    const queryInput = document.getElementById('query') as HTMLInputElement
    const regularBtn = document.getElementById('regular-search-btn')
    const auditBtn = document.getElementById('audit-search-btn')

    const handleRegularSearch = (e: Event) => {
      e.preventDefault()
      const query = queryInput?.value || ''
      if (query) {
        setCurrentQuery(query)
        setCurrentSearchType(undefined)
        performSearch(query)
        // Update URL without causing a page reload
        const url = new URL(window.location.href, window.location.origin)
        url.searchParams.set('query', query)
      }
    }

    const handleAuditSearch = (e: Event) => {
      e.preventDefault()
      const query = queryInput?.value || ''
      if (query) {
        setCurrentQuery(query)
        setCurrentSearchType('audit_log_queries')
        performSearch(query, 'audit_log_queries')
        // Update URL without causing a page reload
        const url = new URL(window.location.href, window.location.origin)
        url.searchParams.set('query', query)
        url.searchParams.set('search_type', 'audit_log_queries')
      }
    }

    if (regularBtn) {
      regularBtn.addEventListener('click', handleRegularSearch)
    }
    if (auditBtn) {
      auditBtn.addEventListener('click', handleAuditSearch)
    }

    // Handle form submission (Enter key)
    const handleFormSubmit = (e: Event) => {
      e.preventDefault()
      handleRegularSearch(e)
    }

    if (form) {
      form.addEventListener('submit', handleFormSubmit)
    }

    return () => {
      if (regularBtn) {
        regularBtn.removeEventListener('click', handleRegularSearch)
      }
      if (auditBtn) {
        auditBtn.removeEventListener('click', handleAuditSearch)
      }
      if (form) {
        form.removeEventListener('submit', handleFormSubmit)
      }
    }
  }, [])

  useEffect(() => {
    if (currentQuery && currentQuery === searchQuery && currentSearchType === searchType) {
      performSearch(currentQuery, currentSearchType)
    }
  }, [currentQuery, currentSearchType, searchQuery, searchType])

  useEffect(() => {
    if (searchResult) {
      if (searchResult.redirectUrl) {
        // Redirect logic
        window.location.href = searchResult.redirectUrl
      }
    }
  }, [searchResult])

  // Render loading message while loading
  if (isLoading) {
    const loadingMessage =
      searchType === 'audit_log_queries' ? 'Loading deleted and renamed users...' : 'Loading search results...'

    return (
      <div>
        <Spinner size="small" />
        <p className="color-fg-muted my-2 mb-0">{loadingMessage}</p>
      </div>
    )
  }

  // Render error message if there was an error
  if (error) {
    return (
      <div>
        <p className="color-fg-danger my-2 mb-0">{error}</p>
      </div>
    )
  }

  /* eslint-disable-next-line @github-ui/github-monorepo/no-cast-as-safe-html-string -- HTML is sanitized server-side. TODO: Move type assertion to data ingress point. */
  return <VerifiedHTMLDiv html={searchResult?.resultsFragment as SafeHTMLString} />
}
